#include <QtCore>
int main(int argc,char **argv){QCoreApplication app(argc,argv);auto args=app.arguments();if(args.size()!=4)return 2;bool a=false,b=false,c=false;int mode=args[1].toInt(&a),threads=args[2].toInt(&b),ms=args[3].toInt(&c);if(!a||!b||!c||mode<0||mode>2||threads<1||threads>256||ms<50||ms>30000)return 2;auto r=gpp_cpu_benchmark(mode,threads,ms);QJsonObject o{{"kind","cpu"},{"method","cpu-portable-v1"},{"mode",mode},{"threads",r.threads},{"seconds",r.seconds},{"operations",double(r.operations)},{"operationsPerSecond",r.operationsPerSecond},{"checksum",r.checksum},{"valid",r.operations>0&&!r.cancelled},{"architecture",QSysInfo::currentCpuArchitecture()}};auto bytes=QJsonDocument(o).toJson(QJsonDocument::Compact);printf("%s\n",bytes.constData());return r.operations?0:1;}
